function D({registerIndicator:N,sourceValues:k,nulls:w}){const y=(l,s,c,u)=>{if(l===""||l===null||l===void 0)return s;const n=Number(l);return Number.isFinite(n)?Math.min(u,Math.max(c,Math.floor(n))):s};N({id:"oa-dwt",name:"Discrete Wavelet Transform (DWT)",category:"Numerics",placement:"pane",inputs:[{key:"source",type:"source",label:"Source",default:"close"},{key:"levels",type:"number",label:"Decomposition Levels",default:4,min:1,max:8,step:1,tooltip:"Number of levels; lookback = 2^levels bars."},{key:"output",type:"number",label:"Output Component",default:0,min:0,max:8,step:1,tooltip:"0 = approximation (trend), 1-8 = detail at that level (noise/cycles). Values above the level count are clamped to the deepest level."}],plots:[{key:"dwt",type:"line",title:"DWT",style:{color:"#ffeb3b",lineWidth:2}}],levels:()=>[{price:0,title:"Zero",color:"#787b86",lineStyle:"dotted"}],calc(l,s){const c=y(s.levels,4,1,8),u=Math.min(y(s.output,0,0,8),c),n=k(l,s.source??"close"),o=l.length,i=new Array(o);for(let e=0;e<o;e++)i[e]=Number.isFinite(n[e])?n[e]:0;const m=new Array(o),b=new Array(o);for(let e=0;e<o;e++){const r=e>=1&&Number.isFinite(n[e-1])?n[e-1]:i[e];m[e]=(i[e]+r)*.5,b[e]=i[e]-m[e]}const d=[i,m],v=[null,b];for(let e=2;e<=8;e++){const r=1<<e-1,a=d[e-1],p=new Array(o),f=new Array(o);for(let t=0;t<o;t++)if(c>=e){const A=t>=r?a[t-r]:a[t];p[t]=(a[t]+A)*.5,f[t]=a[t]-p[t]}else p[t]=a[t],f[t]=0;d.push(p),v.push(f)}const x=u===0?d[c]:v[u],h=new Array(o).fill(NaN);for(let e=0;e<o;e++){const r=x[e];h[e]=Number.isFinite(r)?r:NaN}return{dwt:w(h)}}})}export{D as default};
